	store, err := InitTreasury(path, 1000)
	if err != nil {
		t.Fatal(err)
	}
	in := baseVoteInput("gip-ops")
	in.StartAt, in.Deadline, in.TimelockEnd = 0, 200, 300
	mustCreateVote(t, store, in)
	if _, err := store.CastVote("gip-ops", "alice", true, 0); err != nil {
		t.Fatal(err)
	}
